  "solution": "from typing import List, Tuple
from tessel.bag import Bag

def solve(bag: Bag, total_weight: int) -> List[Tuple[int, int]]:
    heaviest_items = bag.heaviest()
    result = []
    current_weight = 0
    for item, count in heaviest_items:
        if current_weight + item * count >= total_weight:
            result.append((item, count))
            current_weight += item * count
