from tessel.run import Run

def solve(r1, r2):
    result = []
    len_r1, len_r2 = len(r1), len(r2)
    min_len = min(len_r1, len_r2)

    for i in range(min_len):
        result.append(r1[i])
        result.append(r2[i])

    if len_r1 > len_r2:
        result.extend(r1[min_len:])
    elif len_r2 > len_r1:
        result.extend(r2[min_len:])

    return Run(result)
```

