```python
from tessel.bag import Bag

def solve(adds, removes, item):
    b = Bag()
    for add in adds:
        b.drop(add)
    for remove in removes:
        try:
            b.lift(remove)
        except KeyError:
            pass
    return b.weight(item)
```

